module Verified_parser : sig
  type int
  val integer_of_int : int -> Z.t
  type nat
  type char = Chara of bool * bool * bool * bool * bool * bool * bool * bool
  type mtok = FALSE | TRUE | LPA | RPA | LSB | RSB | COM | SC | DOT | QM | LD |
    LESSEQ | EQ | LESS | GTR | GTREQ | STAR | LARROW | SUBSTRING | MATCHES |
    PLUS | MINUS | SLASH | MOD | F2I | I2F | DAY_OF_MONTH | MONTH | YEAR |
    FORMAT_DATE | R2S | S2R | I2S | S2I | F2S | S2F | NAME | STR_CST |
    REGEXP_CST | INTEGER | RAT | TU | LET | LETPAST | FRZ | IN | NOT | AND | OR
    | IMPL | EQUIV | EXISTS | FORALL | PREV | NEXT | EVENTUALLY | ONCE | ALWAYS
    | PAST_ALWAYS | SINCE | TRIGGER | UNTIL | RELEASE | BAR | FREX | PREX | CNT
    | MIN_KW | MAX_KW | SUM_KW | AVG | MED
  type ('a, 'b) sym
  type irel
  type wrel
  type cst = CInt of int | CStr of char list | CFloat of char list |
    CRegexp of char list
  type trm = TVar of char list | TCst of cst | TF2i of trm | TI2f of trm |
    TI2s of trm | TS2i of trm | TF2s of trm | TS2f of trm | TDayOfMonth of trm |
    TMonth of trm | TYear of trm | TFormatDate of trm | TR2s of trm |
    TS2r of trm | TPlus of trm * trm | TMinus of trm * trm | TUMinus of trm |
    TMult of trm * trm | TDiv of trm * trm | TMod of trm * trm
  type bound = OBnd of int | CBnd of int | BInf
  type agg_op = ACnt | AMin | AMax | ASum | AAvg | AMed
  type regex = RSkip of nat | RTest of formula | RConcat of regex * regex |
    RPlus of regex * regex | RStar of regex
  and formula = FEqual of trm * trm | FLess of trm * trm | FLessEq of trm * trm
    | FSubstring of trm * trm | FMatches of trm * trm * (trm option) list |
    FPred of (char list * trm list) |
    FLet of (char list * trm list) * formula * formula |
    FLetPast of (char list * trm list) * formula * formula |
    FFrz of (char list * trm list) * formula * formula | FNeg of formula |
    FAnd of formula * formula | FOr of formula * formula |
    FImplies of formula * formula | FEquiv of formula * formula |
    FExists of (char list) list * formula |
    FForAll of (char list) list * formula |
    FAggreg of char list * agg_op * char list * (char list) list * formula |
    FPrev of (bound * bound) * formula | FNext of (bound * bound) * formula |
    FEventually of (bound * bound) * formula |
    FOnce of (bound * bound) * formula | FAlways of (bound * bound) * formula |
    FPastAlways of (bound * bound) * formula |
    FSince of (bound * bound) * formula * formula |
    FTrigger of (bound * bound) * formula * formula |
    FUntil of (bound * bound) * formula * formula |
    FRelease of (bound * bound) * formula * formula |
    FFrex of (bound * bound) * regex | FPrex of (bound * bound) * regex
  type ('a, 'b, 'c) token_ext
  type ('a, 'b, 'c, 'd) ast
  val lex : char list -> ((mtok, char, unit) token_ext list) option
  val postprocess : formula -> formula option
  val mfodl_parse : (mtok, char, unit) token_ext list -> formula option
  val parse_formula : char list -> formula option
  val integer_of_nat : nat -> Z.t
  val lex_chars : char list -> ((mtok * char list) list) option
end = struct

type int = Int_of_integer of Z.t;;

type num = One | Bit0 of num | Bit1 of num;;

let one_inta : int = Int_of_integer (Z.of_int 1);;

type 'a one = {one : 'a};;
let one _A = _A.one;;

let one_int = ({one = one_inta} : int one);;

let rec integer_of_int (Int_of_integer k) = k;;

let rec plus_inta
  k l = Int_of_integer (Z.add (integer_of_int k) (integer_of_int l));;

type 'a plus = {plus : 'a -> 'a -> 'a};;
let plus _A = _A.plus;;

let plus_int = ({plus = plus_inta} : int plus);;

let zero_inta : int = Int_of_integer Z.zero;;

type 'a zero = {zero : 'a};;
let zero _A = _A.zero;;

let zero_int = ({zero = zero_inta} : int zero);;

type 'a semigroup_add = {plus_semigroup_add : 'a plus};;

type 'a numeral =
  {one_numeral : 'a one; semigroup_add_numeral : 'a semigroup_add};;

let semigroup_add_int = ({plus_semigroup_add = plus_int} : int semigroup_add);;

let numeral_int =
  ({one_numeral = one_int; semigroup_add_numeral = semigroup_add_int} :
    int numeral);;

let rec times_inta
  k l = Int_of_integer (Z.mul (integer_of_int k) (integer_of_int l));;

type 'a times = {times : 'a -> 'a -> 'a};;
let times _A = _A.times;;

type 'a power = {one_power : 'a one; times_power : 'a times};;

let times_int = ({times = times_inta} : int times);;

let power_int = ({one_power = one_int; times_power = times_int} : int power);;

type 'a ab_semigroup_add = {semigroup_add_ab_semigroup_add : 'a semigroup_add};;

type 'a semigroup_mult = {times_semigroup_mult : 'a times};;

type 'a semiring =
  {ab_semigroup_add_semiring : 'a ab_semigroup_add;
    semigroup_mult_semiring : 'a semigroup_mult};;

let ab_semigroup_add_int =
  ({semigroup_add_ab_semigroup_add = semigroup_add_int} :
    int ab_semigroup_add);;

let semigroup_mult_int =
  ({times_semigroup_mult = times_int} : int semigroup_mult);;

let semiring_int =
  ({ab_semigroup_add_semiring = ab_semigroup_add_int;
     semigroup_mult_semiring = semigroup_mult_int}
    : int semiring);;

type 'a mult_zero = {times_mult_zero : 'a times; zero_mult_zero : 'a zero};;

let mult_zero_int =
  ({times_mult_zero = times_int; zero_mult_zero = zero_int} : int mult_zero);;

type 'a monoid_add =
  {semigroup_add_monoid_add : 'a semigroup_add; zero_monoid_add : 'a zero};;

type 'a comm_monoid_add =
  {ab_semigroup_add_comm_monoid_add : 'a ab_semigroup_add;
    monoid_add_comm_monoid_add : 'a monoid_add};;

type 'a semiring_0 =
  {comm_monoid_add_semiring_0 : 'a comm_monoid_add;
    mult_zero_semiring_0 : 'a mult_zero; semiring_semiring_0 : 'a semiring};;

let monoid_add_int =
  ({semigroup_add_monoid_add = semigroup_add_int; zero_monoid_add = zero_int} :
    int monoid_add);;

let comm_monoid_add_int =
  ({ab_semigroup_add_comm_monoid_add = ab_semigroup_add_int;
     monoid_add_comm_monoid_add = monoid_add_int}
    : int comm_monoid_add);;

let semiring_0_int =
  ({comm_monoid_add_semiring_0 = comm_monoid_add_int;
     mult_zero_semiring_0 = mult_zero_int; semiring_semiring_0 = semiring_int}
    : int semiring_0);;

type 'a monoid_mult =
  {semigroup_mult_monoid_mult : 'a semigroup_mult;
    power_monoid_mult : 'a power};;

type 'a semiring_numeral =
  {monoid_mult_semiring_numeral : 'a monoid_mult;
    numeral_semiring_numeral : 'a numeral;
    semiring_semiring_numeral : 'a semiring};;

type 'a zero_neq_one =
  {one_zero_neq_one : 'a one; zero_zero_neq_one : 'a zero};;

type 'a semiring_1 =
  {semiring_numeral_semiring_1 : 'a semiring_numeral;
    semiring_0_semiring_1 : 'a semiring_0;
    zero_neq_one_semiring_1 : 'a zero_neq_one};;

let monoid_mult_int =
  ({semigroup_mult_monoid_mult = semigroup_mult_int;
     power_monoid_mult = power_int}
    : int monoid_mult);;

let semiring_numeral_int =
  ({monoid_mult_semiring_numeral = monoid_mult_int;
     numeral_semiring_numeral = numeral_int;
     semiring_semiring_numeral = semiring_int}
    : int semiring_numeral);;

let zero_neq_one_int =
  ({one_zero_neq_one = one_int; zero_zero_neq_one = zero_int} :
    int zero_neq_one);;

let semiring_1_int =
  ({semiring_numeral_semiring_1 = semiring_numeral_int;
     semiring_0_semiring_1 = semiring_0_int;
     zero_neq_one_semiring_1 = zero_neq_one_int}
    : int semiring_1);;

let rec equal_num x0 x1 = match x0, x1 with Bit0 x2, Bit1 x3 -> false
                    | Bit1 x3, Bit0 x2 -> false
                    | One, Bit1 x3 -> false
                    | Bit1 x3, One -> false
                    | One, Bit0 x2 -> false
                    | Bit0 x2, One -> false
                    | Bit1 x3, Bit1 y3 -> equal_num x3 y3
                    | Bit0 x2, Bit0 y2 -> equal_num x2 y2
                    | One, One -> true;;

type nat = Zero_nat | Nat_of_num of num;;

let rec equal_nata x0 x1 = match x0, x1 with Zero_nat, Zero_nat -> true
                     | Zero_nat, Nat_of_num l -> false
                     | Nat_of_num k, Zero_nat -> false
                     | Nat_of_num k, Nat_of_num l -> equal_num k l;;

type 'a equal = {equal : 'a -> 'a -> bool};;
let equal _A = _A.equal;;

let equal_nat = ({equal = equal_nata} : nat equal);;

let rec plus_num x0 x1 = match x0, x1 with One, One -> Bit0 One
                   | One, Bit0 n -> Bit1 n
                   | One, Bit1 n -> Bit0 (plus_num n One)
                   | Bit0 m, One -> Bit1 m
                   | Bit0 m, Bit0 n -> Bit0 (plus_num m n)
                   | Bit0 m, Bit1 n -> Bit1 (plus_num m n)
                   | Bit1 m, One -> Bit0 (plus_num m One)
                   | Bit1 m, Bit0 n -> Bit1 (plus_num m n)
                   | Bit1 m, Bit1 n -> Bit0 (plus_num (plus_num m n) One);;

let rec times_num
  m n = match m, n with m, One -> m
    | One, n -> n
    | Bit0 m, Bit0 n -> Bit0 (Bit0 (times_num m n))
    | Bit0 m, Bit1 n -> Bit0 (times_num m (Bit1 n))
    | Bit1 m, Bit0 n -> Bit0 (times_num (Bit1 m) n)
    | Bit1 m, Bit1 n -> Bit1 (plus_num (plus_num m n) (Bit0 (times_num m n)));;

let rec times_nata
  m n = match m, n with Zero_nat, n -> Zero_nat
    | m, Zero_nat -> Zero_nat
    | Nat_of_num k, Nat_of_num l -> Nat_of_num (times_num k l);;

type 'a dvd = {times_dvd : 'a times};;

let times_nat = ({times = times_nata} : nat times);;

let dvd_nat = ({times_dvd = times_nat} : nat dvd);;

let one_nata : nat = Nat_of_num One;;

let one_nat = ({one = one_nata} : nat one);;

let rec plus_nata m n = match m, n with Zero_nat, n -> n
                    | m, Zero_nat -> m
                    | Nat_of_num k, Nat_of_num l -> Nat_of_num (plus_num k l);;

let plus_nat = ({plus = plus_nata} : nat plus);;

let zero_nat = ({zero = Zero_nat} : nat zero);;

let semigroup_add_nat = ({plus_semigroup_add = plus_nat} : nat semigroup_add);;

let numeral_nat =
  ({one_numeral = one_nat; semigroup_add_numeral = semigroup_add_nat} :
    nat numeral);;

let power_nat = ({one_power = one_nat; times_power = times_nat} : nat power);;

let rec map_option f x1 = match f, x1 with f, None -> None
                     | f, Some x2 -> Some (f x2);;

let rec dup = function Zero_nat -> Zero_nat
              | Nat_of_num k -> Nat_of_num (Bit0 k);;

let rec bitM = function One -> One
               | Bit0 n -> Bit1 (bitM n)
               | Bit1 n -> Bit1 (Bit0 n);;

let rec minus_nata
  m n = match m, n with Zero_nat, n -> Zero_nat
    | m, Zero_nat -> m
    | Nat_of_num k, Nat_of_num l ->
        (match sub k l with None -> Zero_nat | Some j -> j)
and sub
  x0 x1 = match x0, x1 with One, One -> Some Zero_nat
    | Bit0 m, One -> Some (Nat_of_num (bitM m))
    | Bit1 m, One -> Some (Nat_of_num (Bit0 m))
    | One, Bit0 n -> None
    | One, Bit1 n -> None
    | Bit0 m, Bit0 n -> map_option dup (sub m n)
    | Bit1 m, Bit1 n -> map_option dup (sub m n)
    | Bit1 m, Bit0 n ->
        map_option (fun q -> plus_nata (dup q) (Nat_of_num One)) (sub m n)
    | Bit0 m, Bit1 n ->
        (match sub m n with None -> None
          | Some q ->
            (if equal_nata q Zero_nat then None
              else Some (minus_nata (dup q) (Nat_of_num One))));;

type 'a minus = {minus : 'a -> 'a -> 'a};;
let minus _A = _A.minus;;

let minus_nat = ({minus = minus_nata} : nat minus);;

let rec less_eq_num x0 n = match x0, n with One, n -> true
                      | Bit0 m, One -> false
                      | Bit1 m, One -> false
                      | Bit0 m, Bit0 n -> less_eq_num m n
                      | Bit0 m, Bit1 n -> less_eq_num m n
                      | Bit1 m, Bit1 n -> less_eq_num m n
                      | Bit1 m, Bit0 n -> less_num m n
and less_num m x1 = match m, x1 with m, One -> false
               | One, Bit0 n -> true
               | One, Bit1 n -> true
               | Bit0 m, Bit0 n -> less_num m n
               | Bit0 m, Bit1 n -> less_eq_num m n
               | Bit1 m, Bit1 n -> less_num m n
               | Bit1 m, Bit0 n -> less_num m n;;

let rec less_eq_nat x0 n = match x0, n with Zero_nat, n -> true
                      | Nat_of_num k, Zero_nat -> false
                      | Nat_of_num k, Nat_of_num l -> less_eq_num k l;;

let rec divmod_step_nat
  l qr =
    (let (q, r) = qr in
      (if less_eq_nat l r
        then (plus_nata (times_nata (Nat_of_num (Bit0 One)) q) (Nat_of_num One),
               minus_nata r l)
        else (times_nata (Nat_of_num (Bit0 One)) q, r)));;

let rec divmod_nata
  m x1 = match m, x1 with m, One -> (Nat_of_num m, Zero_nat)
    | One, Bit0 n -> (Zero_nat, Nat_of_num One)
    | One, Bit1 n -> (Zero_nat, Nat_of_num One)
    | Bit0 m, Bit0 n ->
        (let (q, r) = divmod_nata m n in
          (q, times_nata (Nat_of_num (Bit0 One)) r))
    | Bit1 m, Bit0 n ->
        (let (q, r) = divmod_nata m n in
          (q, plus_nata (times_nata (Nat_of_num (Bit0 One)) r)
                (Nat_of_num One)))
    | Bit0 m, Bit1 n ->
        (if less_eq_num m n then (Zero_nat, Nat_of_num (Bit0 m))
          else divmod_step_nat (Nat_of_num (Bit1 n))
                 (divmod_nata (Bit0 m) (Bit0 (Bit1 n))))
    | Bit1 m, Bit1 n ->
        (if less_num m n then (Zero_nat, Nat_of_num (Bit1 m))
          else divmod_step_nat (Nat_of_num (Bit1 n))
                 (divmod_nata (Bit1 m) (Bit0 (Bit1 n))));;

let rec divmod_nat m n = match m, n with Zero_nat, n -> (Zero_nat, Zero_nat)
                     | m, Zero_nat -> (Zero_nat, m)
                     | Nat_of_num k, Nat_of_num l -> divmod_nata k l;;

let rec fst (x1, x2) = x1;;

let rec divide_nata m n = fst (divmod_nat m n);;

type 'a divide = {divide : 'a -> 'a -> 'a};;
let divide _A = _A.divide;;

let divide_nat = ({divide = divide_nata} : nat divide);;

let rec snd (x1, x2) = x2;;

let rec modulo_nata m n = snd (divmod_nat m n);;

type 'a modulo =
  {divide_modulo : 'a divide; dvd_modulo : 'a dvd; modulo : 'a -> 'a -> 'a};;
let modulo _A = _A.modulo;;

let modulo_nat =
  ({divide_modulo = divide_nat; dvd_modulo = dvd_nat; modulo = modulo_nata} :
    nat modulo);;

type 'a ord = {less_eq : 'a -> 'a -> bool; less : 'a -> 'a -> bool};;
let less_eq _A = _A.less_eq;;
let less _A = _A.less;;

let rec less_nat m x1 = match m, x1 with m, Zero_nat -> false
                   | Zero_nat, Nat_of_num l -> true
                   | Nat_of_num k, Nat_of_num l -> less_num k l;;

let ord_nat = ({less_eq = less_eq_nat; less = less_nat} : nat ord);;

type 'a semiring_no_zero_divisors =
  {semiring_0_semiring_no_zero_divisors : 'a semiring_0};;

type 'a semiring_1_no_zero_divisors =
  {semiring_1_semiring_1_no_zero_divisors : 'a semiring_1;
