let rec unset_bit_nat
  n m = (if equal_nata n Zero_nat
          then times_nata (Nat_of_num (Bit0 One))
                 (divide_nata m (Nat_of_num (Bit0 One)))
          else plus_nata (modulo_nata m (Nat_of_num (Bit0 One)))
                 (times_nata (Nat_of_num (Bit0 One))
                   (unset_bit_nat (minus_nata n (Nat_of_num One))
                     (divide_nata m (Nat_of_num (Bit0 One))))));;

