          else (if equal_nata n Zero_nat then m
                 else plus_nata
                        (max ord_nat (modulo_nata m (Nat_of_num (Bit0 One)))
                          (modulo_nata n (Nat_of_num (Bit0 One))))
                        (times_nata (Nat_of_num (Bit0 One))
                          (or_nat (divide_nata m (Nat_of_num (Bit0 One)))
                            (divide_nata n (Nat_of_num (Bit0 One)))))));;

let rec set_bit_nat m n = or_nat n (push_bit_nat m (Nat_of_num One));;

let rec mask_nat
  n = minus_nata (power power_nat (Nat_of_num (Bit0 One)) n) (Nat_of_num One);;

let rec and_nat
  m n = (if equal_nata m Zero_nat || equal_nata n Zero_nat then Zero_nat
          else plus_nata
                 (times_nata (modulo_nata m (Nat_of_num (Bit0 One)))
                   (modulo_nata n (Nat_of_num (Bit0 One))))
                 (times_nata (Nat_of_num (Bit0 One))
                   (and_nat (divide_nata m (Nat_of_num (Bit0 One)))
                     (divide_nata n (Nat_of_num (Bit0 One))))));;

type 'a semiring_bit_operations =
  {semiring_bits_semiring_bit_operations : 'a semiring_bits;
    anda : 'a -> 'a -> 'a; ora : 'a -> 'a -> 'a; xor : 'a -> 'a -> 'a;
    mask : nat -> 'a; set_bit : nat -> 'a -> 'a; unset_bit : nat -> 'a -> 'a;
    flip_bit : nat -> 'a -> 'a; push_bit : nat -> 'a -> 'a;
    drop_bit : nat -> 'a -> 'a; take_bit : nat -> 'a -> 'a};;
let anda _A = _A.anda;;
let ora _A = _A.ora;;
let xor _A = _A.xor;;
let mask _A = _A.mask;;
let set_bit _A = _A.set_bit;;
let unset_bit _A = _A.unset_bit;;
let flip_bit _A = _A.flip_bit;;
let push_bit _A = _A.push_bit;;
let drop_bit _A = _A.drop_bit;;
let take_bit _A = _A.take_bit;;

let semiring_bit_operations_nat =
  ({semiring_bits_semiring_bit_operations = semiring_bits_nat; anda = and_nat;
     ora = or_nat; xor = xor_nat; mask = mask_nat; set_bit = set_bit_nat;
     unset_bit = unset_bit_nat; flip_bit = flip_bit_nat;
     push_bit = push_bit_nat; drop_bit = drop_bit_nat; take_bit = take_bit_nat}
    : nat semiring_bit_operations);;

type 'a linordered_euclidean_semiring_bit_operations =
  {semiring_bit_operations_linordered_euclidean_semiring_bit_operations :
     'a semiring_bit_operations;
    linordered_euclidean_semiring_linordered_euclidean_semiring_bit_operations :
      'a linordered_euclidean_semiring};;

let linordered_euclidean_semiring_bit_operations_nat =
  ({semiring_bit_operations_linordered_euclidean_semiring_bit_operations =
      semiring_bit_operations_nat;
     linordered_euclidean_semiring_linordered_euclidean_semiring_bit_operations
       = linordered_euclidean_semiring_nat}
    : nat linordered_euclidean_semiring_bit_operations);;

let rec equal_lista _A
  x0 x1 = match x0, x1 with [], x21 :: x22 -> false
    | x21 :: x22, [] -> false
    | x21 :: x22, y21 :: y22 -> eq _A x21 y21 && equal_lista _A x22 y22
    | [], [] -> true;;

let rec equal_list _A = ({equal = equal_lista _A} : ('a list) equal);;

let rec equal_bool p pa = match p, pa with false, p -> not p
                     | true, p -> p
                     | p, false -> not p
                     | p, true -> p;;

type char = Chara of bool * bool * bool * bool * bool * bool * bool * bool;;

let rec equal_chara
  (Chara (x1, x2, x3, x4, x5, x6, x7, x8))
    (Chara (y1, y2, y3, y4, y5, y6, y7, y8)) =
    equal_bool x1 y1 &&
      (equal_bool x2 y2 &&
        (equal_bool x3 y3 &&
          (equal_bool x4 y4 &&
            (equal_bool x5 y5 &&
              (equal_bool x6 y6 && (equal_bool x7 y7 && equal_bool x8 y8))))));;

let equal_char = ({equal = equal_chara} : char equal);;

let rec equal_proda _A _B (x1, x2) (y1, y2) = eq _A x1 y1 && eq _B x2 y2;;

let rec equal_prod _A _B = ({equal = equal_proda _A _B} : ('a * 'b) equal);;

