let equal_mtok = ({equal = equal_mtoka} : mtok equal);;

let one_integera : Z.t = (Z.of_int 1);;

let one_integer = ({one = one_integera} : Z.t one);;

let plus_integer = ({plus = Z.add} : Z.t plus);;

let zero_integer = ({zero = Z.zero} : Z.t zero);;

let semigroup_add_integer =
  ({plus_semigroup_add = plus_integer} : Z.t semigroup_add);;

let numeral_integer =
  ({one_numeral = one_integer; semigroup_add_numeral = semigroup_add_integer} :
    Z.t numeral);;

let times_integer = ({times = Z.mul} : Z.t times);;

let power_integer =
  ({one_power = one_integer; times_power = times_integer} : Z.t power);;

let ab_semigroup_add_integer =
  ({semigroup_add_ab_semigroup_add = semigroup_add_integer} :
    Z.t ab_semigroup_add);;

let semigroup_mult_integer =
  ({times_semigroup_mult = times_integer} : Z.t semigroup_mult);;

let semiring_integer =
  ({ab_semigroup_add_semiring = ab_semigroup_add_integer;
     semigroup_mult_semiring = semigroup_mult_integer}
    : Z.t semiring);;

let mult_zero_integer =
  ({times_mult_zero = times_integer; zero_mult_zero = zero_integer} :
    Z.t mult_zero);;

let monoid_add_integer =
  ({semigroup_add_monoid_add = semigroup_add_integer;
     zero_monoid_add = zero_integer}
    : Z.t monoid_add);;

let comm_monoid_add_integer =
  ({ab_semigroup_add_comm_monoid_add = ab_semigroup_add_integer;
     monoid_add_comm_monoid_add = monoid_add_integer}
    : Z.t comm_monoid_add);;

let semiring_0_integer =
  ({comm_monoid_add_semiring_0 = comm_monoid_add_integer;
     mult_zero_semiring_0 = mult_zero_integer;
     semiring_semiring_0 = semiring_integer}
    : Z.t semiring_0);;

let monoid_mult_integer =
  ({semigroup_mult_monoid_mult = semigroup_mult_integer;
     power_monoid_mult = power_integer}
    : Z.t monoid_mult);;

let semiring_numeral_integer =
  ({monoid_mult_semiring_numeral = monoid_mult_integer;
     numeral_semiring_numeral = numeral_integer;
     semiring_semiring_numeral = semiring_integer}
    : Z.t semiring_numeral);;

let zero_neq_one_integer =
  ({one_zero_neq_one = one_integer; zero_zero_neq_one = zero_integer} :
    Z.t zero_neq_one);;

let semiring_1_integer =
  ({semiring_numeral_semiring_1 = semiring_numeral_integer;
     semiring_0_semiring_1 = semiring_0_integer;
     zero_neq_one_semiring_1 = zero_neq_one_integer}
    : Z.t semiring_1);;

type ('a, 'b) sym = Nt of 'a | Tm of 'b;;

let rec equal_syma _A _B x0 x1 = match x0, x1 with Nt x1, Tm x2 -> false
                           | Tm x2, Nt x1 -> false
                           | Tm x2, Tm y2 -> eq _B x2 y2
                           | Nt x1, Nt y1 -> eq _A x1 y1;;

let rec equal_sym _A _B = ({equal = equal_syma _A _B} : ('a, 'b) sym equal);;

type irel = Eq | Gt | Ge | Any;;

let rec equal_irela x0 x1 = match x0, x1 with Ge, Any -> false
                      | Any, Ge -> false
                      | Gt, Any -> false
                      | Any, Gt -> false
                      | Gt, Ge -> false
                      | Ge, Gt -> false
                      | Eq, Any -> false
                      | Any, Eq -> false
                      | Eq, Ge -> false
                      | Ge, Eq -> false
                      | Eq, Gt -> false
                      | Gt, Eq -> false
                      | Any, Any -> true
                      | Ge, Ge -> true
                      | Gt, Gt -> true
                      | Eq, Eq -> true;;

let equal_irel = ({equal = equal_irela} : irel equal);;

type wrel = WEq | WGe | WGt | WLe | WLt | WAny;;

type ('a, 'b) dact = DShift | DReduce of ('a * (('a, 'b) sym * irel) list);;

type cst = CInt of int | CStr of char list | CFloat of char list |
  CRegexp of char list;;

type trm = TVar of char list | TCst of cst | TF2i of trm | TI2f of trm |
  TI2s of trm | TS2i of trm | TF2s of trm | TS2f of trm | TDayOfMonth of trm |
  TMonth of trm | TYear of trm | TFormatDate of trm | TR2s of trm | TS2r of trm
  | TPlus of trm * trm | TMinus of trm * trm | TUMinus of trm |
  TMult of trm * trm | TDiv of trm * trm | TMod of trm * trm;;

type action = Emit of mtok | Skip | Comment | LineComment | EmitTU;;

type bound = OBnd of int | CBnd of int | BInf;;

type agg_op = ACnt | AMin | AMax | ASum | AAvg | AMed;;

type regex = RSkip of nat | RTest of formula | RConcat of regex * regex |
  RPlus of regex * regex | RStar of regex
and formula = FEqual of trm * trm | FLess of trm * trm | FLessEq of trm * trm |
  FSubstring of trm * trm | FMatches of trm * trm * (trm option) list |
  FPred of (char list * trm list) |
  FLet of (char list * trm list) * formula * formula |
  FLetPast of (char list * trm list) * formula * formula |
  FFrz of (char list * trm list) * formula * formula | FNeg of formula |
  FAnd of formula * formula | FOr of formula * formula |
  FImplies of formula * formula | FEquiv of formula * formula |
  FExists of (char list) list * formula | FForAll of (char list) list * formula
  | FAggreg of char list * agg_op * char list * (char list) list * formula |
  FPrev of (bound * bound) * formula | FNext of (bound * bound) * formula |
  FEventually of (bound * bound) * formula | FOnce of (bound * bound) * formula
  | FAlways of (bound * bound) * formula |
  FPastAlways of (bound * bound) * formula |
  FSince of (bound * bound) * formula * formula |
  FTrigger of (bound * bound) * formula * formula |
  FUntil of (bound * bound) * formula * formula |
  FRelease of (bound * bound) * formula * formula |
  FFrex of (bound * bound) * regex | FPrex of (bound * bound) * regex;;

type ('a, 'b) span_ext = Span_ext of nat * nat * nat * nat * 'a list * 'b;;

type ('a, 'b, 'c) token_ext = Token_ext of 'a * ('b, unit) span_ext * 'c;;

type ('a, 'b, 'c, 'd) ast = Leaf of ('d, 'b, 'a) token_ext |
  Node of 'c * ('a, 'b, 'c, 'd) ast list;;

let rec suc n = plus_nata n (Nat_of_num One);;

let rec comp f g = (fun x -> f (g x));;

let rec nth
  (x :: xs) n =
    (if equal_nata n Zero_nat then x
      else nth xs (minus_nata n (Nat_of_num One)));;

let rec fold f x1 s = match f, x1, s with f, [], s -> s
               | f, x :: xs, s -> fold f xs (f x s);;

let rec rev xs = fold (fun a b -> a :: b) xs [];;

let rec drop
  n x1 = match n, x1 with n, [] -> []
    | n, x :: xs ->
        (if equal_nata n Zero_nat then x :: xs
          else drop (minus_nata n (Nat_of_num One)) xs);;

let rec null = function [] -> true
               | x :: xs -> false;;

let rec last (x :: xs) = (if null xs then x else last xs);;

let rec maps f x1 = match f, x1 with f, [] -> []
               | f, x :: xs -> f x @ maps f xs;;

let rec take
  n x1 = match n, x1 with n, [] -> []
    | n, x :: xs ->
        (if equal_nata n Zero_nat then []
          else x :: take (minus_nata n (Nat_of_num One)) xs);;

let rec length_tailrec x0 n = match x0, n with [], n -> n
                         | x :: xs, n -> length_tailrec xs (suc n);;

let rec size_list xs = length_tailrec xs Zero_nat;;

let rec min _A a b = (if less_eq _A a b then a else b);;

let rec map_of _A
  x0 k = match x0, k with [], k -> None
    | (l, v) :: ps, k -> (if eq _A l k then Some v else map_of _A ps k);;

let rec la_next _A _B
  gt sts i x =
    min ord_nat
      (match map_of (equal_sym _A _B) (nth gt i) x with None -> size_list sts
        | Some j -> j)
      (size_list sts);;

let rec foldl f a x2 = match f, a, x2 with f, a, [] -> a
                | f, a, x :: xs -> foldl f (f a x) xs;;

let rec foldr f x1 = match f, x1 with f, [] -> id
                | f, x :: xs -> comp (f x) (foldr f xs);;

let rec filter
  p x1 = match p, x1 with p, [] -> []
    | p, x :: xs -> (if p x then x :: filter p xs else filter p xs);;

let rec member _A x0 y = match x0, y with [], y -> false
                    | x :: xs, y -> eq _A x y || member _A xs y;;

let rec bind x0 f = match x0, f with None, f -> None
               | Some x, f -> f x;;

let rec butlast = function [] -> []
                  | x :: xs -> (if null xs then [] else x :: butlast xs);;

let rec hd (x21 :: x22) = x21;;

let rec tl = function [] -> []
             | x21 :: x22 -> x22;;

let rec list_ex p x1 = match p, x1 with p, [] -> false
                  | p, x :: xs -> p x || list_ex p xs;;

let rec map f x1 = match f, x1 with f, [] -> []
              | f, x21 :: x22 -> f x21 :: map f x22;;

let rec list_all p x1 = match p, x1 with p, [] -> true
                   | p, x :: xs -> p x && list_all p xs;;

let rec superset _A xs = list_all (member _A xs);;

let rec tok (Token_ext (tok, span, more)) = tok;;

let rec dnext _A _B
  gt sts i x =
    (if less_nat i (size_list gt) then la_next _A _B gt sts i x
      else size_list sts);;

let rec starget _A _B
  pgt psts stk v act =
    (match act
      with DShift ->
        (match v with [] -> None
          | x :: _ ->
            (let q = dnext _A _B pgt psts (snd (hd stk)) (Tm (tok x)) in
              (if less_nat q (size_list psts) then Some q else None)))
      | DReduce pr ->
        (if less_nat (size_list (snd pr)) (size_list stk)
          then (let q =
                  dnext _A _B pgt psts (snd (nth stk (size_list (snd pr))))
                    (Nt (fst pr))
                  in
                 (if less_nat q (size_list psts) then Some q else None))
          else None));;

let rec map_filter
  f x1 = match f, x1 with f, [] -> []
    | f, x :: xs ->
        (match f x with None -> map_filter f xs
          | Some y -> y :: map_filter f xs);;

let rec equal_option _A x0 x1 = match x0, x1 with None, Some x2 -> false
                          | Some x2, None -> false
                          | Some x2, Some y2 -> eq _A x2 y2
                          | None, None -> true;;

let rec is_none = function None -> true
                  | Some x -> false;;

let rec slic _A _B
  i cells v pr =
    list_ex
      (fun (ia, (itm, (t, _))) ->
        equal_nata ia i &&
          (equal_proda
             (equal_prod _A
               (equal_list (equal_prod (equal_sym _A _B) equal_irel)))
             equal_nat itm (pr, size_list (snd pr)) &&
            (match v with [] -> is_none t
              | x :: _ -> equal_option _B t (Some (tok x)))))
      cells;;

let rec scands _A _B
  comps i cells v =
    (let reds =
       map_filter
         (fun x -> (if slic _A _B i cells v x then Some (DReduce x) else None))
         comps
       in
      (match v with [] -> reds | _ :: _ -> DShift :: reds));;

let rec spick
  f x1 = match f, x1 with f, [] -> None
    | f, a :: asa ->
        (match f a with None -> spick f asa | Some b -> Some (a, b));;

let rec sctl _A _B
  gt sts redtab pgt psts pc c =
    (let (stk, v) = c in
      (match stk with [] -> None
        | (i, p) :: _ ->
          (let cells =
             (if less_nat i (size_list redtab) then nth redtab i else []) in
           let comps = (if less_nat p (size_list pc) then nth pc p else []) in
            (match
              spick (starget _A _B pgt psts stk v)
                (scands _A _B comps i cells v)
              with None -> None
              | Some (act, q) ->
                Some (act, (match act
                             with DShift ->
                               ((dnext _A _B gt sts i (Tm (tok (hd v))), q) ::
                                  stk,
                                 tl v)
                             | DReduce pr ->
                               ((dnext _A _B gt sts
                                   (fst (nth stk (size_list (snd pr))))
                                   (Nt (fst pr)),
                                  q) ::
                                  drop (size_list (snd pr)) stk,
                                 v)))))));;

let rec takeWhile p x1 = match p, x1 with p, [] -> []
                    | p, x :: xs -> (if p x then x :: takeWhile p xs else []);;

let rec stree
  act v tstk =
    (match act with DShift -> Leaf (hd v) :: tstk
      | DReduce pr ->
        Node (fst pr, rev (take (size_list (snd pr)) tstk)) ::
          drop (size_list (snd pr)) tstk);;

let rec comment_end
  = function
    c :: d :: s ->
      (if equal_chara c
            (Chara (false, true, false, true, false, true, false, false)) &&
            equal_chara d
              (Chara (true, false, false, true, false, true, false, false))
        then Some (Nat_of_num (Bit0 One))
        else map_option suc (comment_end (d :: s)))
    | [] -> None
    | [v] -> None;;

let rec valid_unit
  lx = member equal_char
         [Chara (false, false, true, false, false, true, true, false);
           Chara (false, false, false, true, false, true, true, false);
           Chara (true, false, true, true, false, true, true, false);
           Chara (true, true, false, false, true, true, true, false)]
         (last lx);;

let rec best_match
  b x1 s = match b, x1, s with b, [], s -> b
    | b, (m, a) :: rs, s ->
        best_match
          (match m s with None -> b
            | Some n ->
              (match b with None -> Some (n, a)
                | Some (na, _) -> (if less_nat na n then Some (n, a) else b)))
          rs s;;

let rec mk_token
  t off lx =
    Token_ext (t, Span_ext (Zero_nat, off, off, size_list lx, lx, ()), ());;

let rec line_end
  s = (let n =
         size_list
           (takeWhile
             (fun c ->
               not (equal_chara c
                     (Chara
                       (false, true, false, true, false, false, false,
                         false))) &&
                 not (equal_chara c
                       (Chara
                         (true, false, true, true, false, false, false,
                           false))))
             s)
         in
        (if less_nat n (size_list s) then suc n else n));;

