         Chara (false, true, true, true, false, false, true, false)],
        MIN_KW);
      ([Chara (true, false, true, true, false, false, true, false);
         Chara (true, false, false, false, false, false, true, false);
         Chara (false, false, false, true, true, false, true, false)],
        MAX_KW);
      ([Chara (true, true, false, false, true, false, true, false);
         Chara (true, false, true, false, true, false, true, false);
         Chara (true, false, true, true, false, false, true, false)],
        SUM_KW);
      ([Chara (true, false, false, false, false, false, true, false);
         Chara (false, true, true, false, true, false, true, false);
         Chara (true, true, true, false, false, false, true, false)],
        AVG);
      ([Chara (true, false, true, true, false, false, true, false);
         Chara (true, false, true, false, false, false, true, false);
         Chara (false, false, true, false, false, false, true, false)],
        MED)];;

let rec horner_sum _B
  f a xs =
    foldr (fun x b ->
            plus _B.semiring_0_comm_semiring_0.comm_monoid_add_semiring_0.monoid_add_comm_monoid_add.semigroup_add_monoid_add.plus_semigroup_add
              (f x)
              (times
                _B.semiring_0_comm_semiring_0.mult_zero_semiring_0.times_mult_zero
                a b))
      xs (zero _B.semiring_0_comm_semiring_0.mult_zero_semiring_0.zero_mult_zero);;

let rec of_bool _A = function false -> zero _A.zero_zero_neq_one
                     | true -> one _A.one_zero_neq_one;;

let rec numeral _A
  = function One -> one _A.one_numeral
    | Bit0 n ->
        (let m = numeral _A n in
          plus _A.semigroup_add_numeral.plus_semigroup_add m m)
    | Bit1 n ->
        (let m = numeral _A n in
          plus _A.semigroup_add_numeral.plus_semigroup_add
            (plus _A.semigroup_add_numeral.plus_semigroup_add m m)
            (one _A.one_numeral));;

let rec digit7 (Chara (x1, x2, x3, x4, x5, x6, x7, x8)) = x8;;

let rec digit6 (Chara (x1, x2, x3, x4, x5, x6, x7, x8)) = x7;;

let rec digit5 (Chara (x1, x2, x3, x4, x5, x6, x7, x8)) = x6;;

let rec digit4 (Chara (x1, x2, x3, x4, x5, x6, x7, x8)) = x5;;

let rec digit3 (Chara (x1, x2, x3, x4, x5, x6, x7, x8)) = x4;;

let rec digit2 (Chara (x1, x2, x3, x4, x5, x6, x7, x8)) = x3;;

let rec digit1 (Chara (x1, x2, x3, x4, x5, x6, x7, x8)) = x2;;

let rec digit0 (Chara (x1, x2, x3, x4, x5, x6, x7, x8)) = x1;;

let rec of_char _A
  c = horner_sum _A.comm_semiring_0_comm_semiring_1
        (of_bool _A.semiring_1_comm_semiring_1.zero_neq_one_semiring_1)
        (numeral
          _A.semiring_1_comm_semiring_1.semiring_numeral_semiring_1.numeral_semiring_numeral
          (Bit0 One))
        [digit0 c; digit1 c; digit2 c; digit3 c; digit4 c; digit5 c; digit6 c;
          digit7 c];;

let rec in_range
  a b c =
    less_eq_nat (of_char comm_semiring_1_nat a)
      (of_char comm_semiring_1_nat c) &&
      less_eq_nat (of_char comm_semiring_1_nat c)
        (of_char comm_semiring_1_nat b);;

let rec is_letter
  c = in_range (Chara (true, false, false, false, false, true, true, false))
        (Chara (false, true, false, true, true, true, true, false)) c ||
        in_range (Chara (true, false, false, false, false, false, true, false))
          (Chara (false, true, false, true, true, false, true, false)) c;;

let rec is_digit
  c = in_range (Chara (false, false, false, false, true, true, false, false))
        (Chara (true, false, false, true, true, true, false, false)) c;;

let rec is_str_start
  c = is_letter c ||
        (is_digit c ||
          equal_chara c
            (Chara (true, true, true, true, true, false, true, false)));;

let rec is_str_char
  c = is_str_start c ||
        (member equal_char
           [Chara (true, false, true, true, false, true, false, false);
             Chara (true, true, true, true, false, true, false, false);
             Chara (false, true, false, true, true, true, false, false)]
           c ||
          (equal_chara c
             (Chara (true, true, true, false, false, true, false, false)) ||
            equal_chara c
              (Chara (false, true, false, false, false, true, false, false))));;

let rec m_string
  s = (match s with [] -> None
        | c :: sa ->
          (if is_str_start c
            then Some (suc (size_list (takeWhile is_str_char sa))) else None));;

let rec q_body
  = function [] -> None
    | c :: s ->
        (if equal_chara c
              (Chara (false, true, false, false, false, true, false, false))
          then Some (Nat_of_num One)
          else (if equal_chara c
                     (Chara
                       (false, false, true, true, true, false, true, false))
                 then (match s with [] -> None
                        | _ :: sa ->
                          map_option
                            (fun n -> plus_nata n (Nat_of_num (Bit0 One)))
                            (q_body sa))
                 else map_option suc (q_body s)));;

let rec m_quoted
  s = (match s with [] -> None
        | c :: sa ->
          (if equal_chara c
                (Chara (false, true, false, false, false, true, false, false))
            then map_option suc (q_body sa) else None));;

let rec m_regexp
  s = (match s with [] -> None
        | c :: sa ->
          (if equal_chara c
                (Chara (false, true, false, false, true, true, true, false))
            then map_option suc (m_quoted sa) else None));;

let rec is_space
  c = member equal_char
        [Chara (false, false, false, false, false, true, false, false);
          Chara (true, false, false, true, false, false, false, false);
          Chara (false, true, false, true, false, false, false, false);
          Chara (true, false, true, true, false, false, false, false)]
        c;;

let rec m_space
  s = (match s with [] -> None
        | c :: _ -> (if is_space c then Some (Nat_of_num One) else None));;

let rec m_fixed
  k s = (if not (null k) && equal_lista equal_char (take (size_list k) s) k
          then Some (size_list k) else None);;

let rec count_digits s = size_list (takeWhile is_digit s);;

let rec m_unit
  s = (let n = count_digits s in
        (if less_nat Zero_nat n &&
              (less_nat n (size_list s) && is_letter (nth s n))
          then Some (suc n) else None));;

let rec sign_len
  s = (match s with [] -> Zero_nat
        | Chara (true, true, _, _, _, _, _, _) :: _ -> Zero_nat
        | Chara (true, false, true, true, true, _, _, _) :: _ -> Zero_nat
        | Chara (true, false, true, true, false, true, true, _) :: _ -> Zero_nat
        | Chara (true, false, true, true, false, true, false, true) :: _ ->
          Zero_nat
        | Chara (true, false, true, true, false, true, false, false) :: _ ->
          Nat_of_num One
        | Chara (true, false, true, true, false, false, _, _) :: _ -> Zero_nat
        | Chara (true, false, true, false, _, _, _, _) :: _ -> Zero_nat
        | Chara (true, false, false, _, _, _, _, _) :: _ -> Zero_nat
        | Chara (false, _, _, _, _, _, _, _) :: _ -> Zero_nat);;

let rec m_rat
  s = (let k = sign_len s in
       let n = count_digits (drop k s) in
        (if less_nat Zero_nat n &&
              (less_nat (plus_nata k n) (size_list s) &&
                equal_chara (nth s (plus_nata k n))
                  (Chara (false, true, true, true, false, true, false, false)))
          then Some (plus_nata (plus_nata (plus_nata k n) (Nat_of_num One))
                      (count_digits
                        (drop (plus_nata (plus_nata k n) (Nat_of_num One)) s)))
          else None));;

let rec m_int
  s = (let k = sign_len s in
       let n = count_digits (drop k s) in
        (if less_nat Zero_nat n then Some (plus_nata k n) else None));;

let rules : ((char list -> nat option) * action) list
  = [(m_space, Skip)] @
      map (fun (k, t) -> (m_fixed k, Emit t)) keyword_table @
        [(m_unit, EmitTU); (m_int, Emit INTEGER); (m_rat, Emit RAT);
          (m_quoted, Emit STR_CST); (m_regexp, Emit REGEXP_CST);
          (m_string, Emit NAME);
          (m_fixed
             [Chara (false, false, false, true, false, true, false, false);
               Chara (false, true, false, true, false, true, false, false)],
            Comment);
          (m_fixed
             [Chara (true, true, false, false, false, true, false, false)],
            LineComment)];;

let rec lex_aux
  uu uv x2 = match uu, uv, x2 with uu, uv, [] -> Some []
    | fuel, uw, v :: va ->
        (if equal_nata fuel Zero_nat then None
          else (match best_match None rules (v :: va) with None -> None
                 | Some (n, a) ->
                   (let lx = take n (v :: va) in
                    let rest = drop n (v :: va) in
                     (match a
                       with Emit t ->
                         map_option (fun aa -> mk_token t uw lx :: aa)
                           (lex_aux (minus_nata fuel (Nat_of_num One))
                             (plus_nata uw n) rest)
                       | Skip ->
                         lex_aux (minus_nata fuel (Nat_of_num One))
                           (plus_nata uw n) rest
                       | Comment ->
                         (match comment_end rest with None -> None
                           | Some k ->
                             lex_aux (minus_nata fuel (Nat_of_num One))
                               (plus_nata (plus_nata uw n) k) (drop k rest))
                       | LineComment ->
                         (let k = line_end rest in
                           lex_aux (minus_nata fuel (Nat_of_num One))
                             (plus_nata (plus_nata uw n) k) (drop k rest))
                       | EmitTU ->
                         (if valid_unit lx
                           then map_option (fun aa -> mk_token TU uw lx :: aa)
                                  (lex_aux (minus_nata fuel (Nat_of_num One))
                                    (plus_nata uw n) rest)
                           else None)))));;

let rec lex s = lex_aux (size_list s) Zero_nat s;;

let rec tvars = function TVar v -> [v]
                | TCst uu -> []
                | TF2i t -> tvars t
                | TI2f t -> tvars t
                | TI2s t -> tvars t
                | TS2i t -> tvars t
                | TF2s t -> tvars t
                | TS2f t -> tvars t
                | TDayOfMonth t -> tvars t
                | TMonth t -> tvars t
                | TYear t -> tvars t
                | TFormatDate t -> tvars t
                | TR2s t -> tvars t
                | TS2r t -> tvars t
                | TUMinus t -> tvars t
                | TPlus (t, u) -> tvars t @ tvars u
                | TMinus (t, u) -> tvars t @ tvars u
                | TMult (t, u) -> tvars t @ tvars u
                | TDiv (t, u) -> tvars t @ tvars u
                | TMod (t, u) -> tvars t @ tvars u;;

let rec pvars
  p = maps (fun a ->
             (match a with TVar v -> [v] | TCst _ -> [] | TF2i _ -> []
               | TI2f _ -> [] | TI2s _ -> [] | TS2i _ -> [] | TF2s _ -> []
               | TS2f _ -> [] | TDayOfMonth _ -> [] | TMonth _ -> []
               | TYear _ -> [] | TFormatDate _ -> [] | TR2s _ -> []
               | TS2r _ -> [] | TPlus (_, _) -> [] | TMinus (_, _) -> []
               | TUMinus _ -> [] | TMult (_, _) -> [] | TDiv (_, _) -> []
               | TMod (_, _) -> []))
        (snd p);;

let rec fv_f
  = function FEqual (t, u) -> tvars t @ tvars u
    | FLess (t, u) -> tvars t @ tvars u
    | FLessEq (t, u) -> tvars t @ tvars u
    | FSubstring (t, u) -> tvars t @ tvars u
    | FMatches (t, u, ts) -> tvars t @ tvars u @ maps tvars (map_filter id ts)
    | FPred p -> pvars p
    | FLet (uu, uv, g) -> fv_f g
    | FLetPast (uw, ux, g) -> fv_f g
    | FFrz (uy, uz, g) -> fv_f g
    | FNeg f -> fv_f f
    | FAnd (f, g) -> fv_f f @ fv_f g
    | FOr (f, g) -> fv_f f @ fv_f g
    | FImplies (f, g) -> fv_f f @ fv_f g
    | FEquiv (f, g) -> fv_f f @ fv_f g
    | FExists (vs, f) ->
        filter (fun v -> not (member (equal_list equal_char) vs v)) (fv_f f)
    | FForAll (vs, f) ->
        filter (fun v -> not (member (equal_list equal_char) vs v)) (fv_f f)
    | FAggreg (y, va, vb, g, vc) -> y :: g
    | FPrev (vd, f) -> fv_f f
    | FNext (ve, f) -> fv_f f
    | FEventually (vf, f) -> fv_f f
    | FOnce (vg, f) -> fv_f f
    | FAlways (vh, f) -> fv_f f
    | FPastAlways (vi, f) -> fv_f f
    | FSince (vj, f, g) -> fv_f f @ fv_f g
    | FTrigger (vk, f, g) -> fv_f f @ fv_f g
    | FUntil (vl, f, g) -> fv_f f @ fv_f g
    | FRelease (vm, f, g) -> fv_f f @ fv_f g
    | FFrex (vn, r) -> fv_r r
    | FPrex (vo, r) -> fv_r r
and fv_r = function RSkip vp -> []
           | RTest f -> fv_f f
           | RConcat (r, s) -> fv_r r @ fv_r s
           | RPlus (r, s) -> fv_r r @ fv_r s
           | RStar r -> fv_r r;;

let rec is_anon
  v = (match v with [] -> false
        | c :: _ ->
          equal_chara c
            (Chara (true, true, true, true, true, false, true, false)));;

let rec anon_vars
  p = maps (fun a ->
             (match a with TVar v -> (if is_anon v then [v] else [])
               | TCst _ -> [] | TF2i _ -> [] | TI2f _ -> [] | TI2s _ -> []
               | TS2i _ -> [] | TF2s _ -> [] | TS2f _ -> []
               | TDayOfMonth _ -> [] | TMonth _ -> [] | TYear _ -> []
               | TFormatDate _ -> [] | TR2s _ -> [] | TS2r _ -> []
               | TPlus (_, _) -> [] | TMinus (_, _) -> [] | TUMinus _ -> []
               | TMult (_, _) -> [] | TDiv (_, _) -> [] | TMod (_, _) -> []))
        (snd p);;

let rec def_ok p = null (anon_vars p);;

let rec ok_f
  = function FLet (p, f, g) -> def_ok p && (ok_f f && ok_f g)
    | FLetPast (p, f, g) -> def_ok p && (ok_f f && ok_f g)
    | FFrz (p, f, g) -> def_ok p && (ok_f f && ok_f g)
    | FNeg f -> ok_f f
    | FAnd (f, g) -> ok_f f && ok_f g
    | FOr (f, g) -> ok_f f && ok_f g
    | FImplies (f, g) -> ok_f f && ok_f g
    | FEquiv (f, g) -> ok_f f && ok_f g
    | FExists (vs, f) -> not (null vs) && ok_f f
    | FForAll (vs, f) -> not (null vs) && ok_f f
    | FAggreg (y, op, x, g, f) ->
        member (equal_list equal_char) (fv_f f) x &&
          (superset (equal_list equal_char) (fv_f f) g && ok_f f)
    | FPrev (uu, f) -> ok_f f
    | FNext (uv, f) -> ok_f f
    | FEventually (uw, f) -> ok_f f
    | FOnce (ux, f) -> ok_f f
    | FAlways (uy, f) -> ok_f f
    | FPastAlways (uz, f) -> ok_f f
    | FSince (va, f, g) -> ok_f f && ok_f g
    | FTrigger (vb, f, g) -> ok_f f && ok_f g
    | FUntil (vc, f, g) -> ok_f f && ok_f g
    | FRelease (vd, f, g) -> ok_f f && ok_f g
    | FFrex (ve, r) -> ok_r r
    | FPrex (vf, r) -> ok_r r
    | FEqual (v, va) -> true
    | FLess (v, va) -> true
    | FLessEq (v, va) -> true
    | FSubstring (v, va) -> true
    | FMatches (v, va, vb) -> true
    | FPred v -> true
and ok_r = function RTest f -> ok_f f
           | RConcat (r, s) -> ok_r r && ok_r s
           | RPlus (r, s) -> ok_r r && ok_r s
           | RStar r -> ok_r r
           | RSkip v -> true;;

let rec sfinal
  pf c =
    (let (stk, v) = c in
      null v &&
        (not (null stk) &&
          (less_nat (snd (hd stk)) (size_list pf) && nth pf (snd (hd stk)))));;

let rec s_txt (Span_ext (s_line, s_col, s_off, s_len, s_txt, more)) = s_txt;;

let rec span (Token_ext (tok, span, more)) = span;;

let rec sresult tstk = (match tstk with [] -> None | t :: _ -> Some t);;

let wild : regex = RSkip (Nat_of_num One);;

let rec equal_dact _A _B
  x0 x1 = match x0, x1 with DShift, DReduce x2 -> false
    | DReduce x2, DShift -> false
    | DReduce x2, DReduce y2 ->
        equal_proda _A (equal_list (equal_prod (equal_sym _A _B) equal_irel)) x2
          y2
    | DShift, DShift -> true;;

let rec srun_hist _A _B
  gt sts redtab pgt psts pc pf seen st =
    (let (stk, (v, tstk)) = st in
      (if sfinal pf (stk, v) then sresult tstk
        else (if member (equal_list (equal_prod equal_nat equal_nat)) seen stk
               then None
               else bind (sctl _A _B gt sts redtab pgt psts pc (stk, v))
                      (fun (act, (stka, va)) ->
                        srun_hist _A _B gt sts redtab pgt psts pc pf
                          (if equal_dact _A _B act DShift then []
                            else stk :: seen)
                          (stka, (va, stree act v tstk))))));;

let rec add_ex_f
  = function
    FPred p ->
      (if null (anon_vars p) then FPred p else FExists (anon_vars p, FPred p))
    | FLet (p, f, g) -> FLet (p, add_ex_f f, add_ex_f g)
    | FLetPast (p, f, g) -> FLetPast (p, add_ex_f f, add_ex_f g)
    | FFrz (p, f, g) -> FFrz (p, add_ex_f f, add_ex_f g)
    | FNeg f -> FNeg (add_ex_f f)
    | FAnd (f, g) -> FAnd (add_ex_f f, add_ex_f g)
    | FOr (f, g) -> FOr (add_ex_f f, add_ex_f g)
    | FImplies (f, g) -> FImplies (add_ex_f f, add_ex_f g)
    | FEquiv (f, g) -> FEquiv (add_ex_f f, add_ex_f g)
    | FExists (vs, f) -> FExists (vs, add_ex_f f)
    | FForAll (vs, f) -> FForAll (vs, add_ex_f f)
    | FAggreg (y, op, x, g, f) -> FAggreg (y, op, x, g, add_ex_f f)
    | FPrev (i, f) -> FPrev (i, add_ex_f f)
    | FNext (i, f) -> FNext (i, add_ex_f f)
    | FEventually (i, f) -> FEventually (i, add_ex_f f)
    | FOnce (i, f) -> FOnce (i, add_ex_f f)
    | FAlways (i, f) -> FAlways (i, add_ex_f f)
    | FPastAlways (i, f) -> FPastAlways (i, add_ex_f f)
    | FSince (i, f, g) -> FSince (i, add_ex_f f, add_ex_f g)
    | FTrigger (i, f, g) -> FTrigger (i, add_ex_f f, add_ex_f g)
    | FUntil (i, f, g) -> FUntil (i, add_ex_f f, add_ex_f g)
    | FRelease (i, f, g) -> FRelease (i, add_ex_f f, add_ex_f g)
    | FFrex (i, r) -> FFrex (i, add_ex_r r)
    | FPrex (i, r) -> FPrex (i, add_ex_r r)
    | FEqual (v, va) -> FEqual (v, va)
    | FLess (v, va) -> FLess (v, va)
    | FLessEq (v, va) -> FLessEq (v, va)
    | FSubstring (v, va) -> FSubstring (v, va)
    | FMatches (v, va, vb) -> FMatches (v, va, vb)
and add_ex_r = function RTest f -> RTest (add_ex_f f)
               | RConcat (r, s) -> RConcat (add_ex_r r, add_ex_r s)
               | RPlus (r, s) -> RPlus (add_ex_r r, add_ex_r s)
               | RStar r -> RStar (add_ex_r r)
               | RSkip v -> RSkip v;;

let rec equal_int k l = Z.equal (integer_of_int k) (integer_of_int l);;

let rec equal_cst x0 x1 = match x0, x1 with CFloat x3, CRegexp x4 -> false
                    | CRegexp x4, CFloat x3 -> false
                    | CStr x2, CRegexp x4 -> false
                    | CRegexp x4, CStr x2 -> false
                    | CStr x2, CFloat x3 -> false
                    | CFloat x3, CStr x2 -> false
                    | CInt x1, CRegexp x4 -> false
                    | CRegexp x4, CInt x1 -> false
                    | CInt x1, CFloat x3 -> false
                    | CFloat x3, CInt x1 -> false
                    | CInt x1, CStr x2 -> false
                    | CStr x2, CInt x1 -> false
                    | CRegexp x4, CRegexp y4 -> equal_lista equal_char x4 y4
                    | CFloat x3, CFloat y3 -> equal_lista equal_char x3 y3
                    | CStr x2, CStr y2 -> equal_lista equal_char x2 y2
                    | CInt x1, CInt y1 -> equal_int x1 y1;;

let rec equal_trm
  x0 x1 = match x0, x1 with TDiv (x191, x192), TMod (x201, x202) -> false
    | TMod (x201, x202), TDiv (x191, x192) -> false
    | TMult (x181, x182), TMod (x201, x202) -> false
    | TMod (x201, x202), TMult (x181, x182) -> false
    | TMult (x181, x182), TDiv (x191, x192) -> false
    | TDiv (x191, x192), TMult (x181, x182) -> false
    | TUMinus x17, TMod (x201, x202) -> false
    | TMod (x201, x202), TUMinus x17 -> false
    | TUMinus x17, TDiv (x191, x192) -> false
    | TDiv (x191, x192), TUMinus x17 -> false
    | TUMinus x17, TMult (x181, x182) -> false
    | TMult (x181, x182), TUMinus x17 -> false
    | TMinus (x161, x162), TMod (x201, x202) -> false
    | TMod (x201, x202), TMinus (x161, x162) -> false
    | TMinus (x161, x162), TDiv (x191, x192) -> false
    | TDiv (x191, x192), TMinus (x161, x162) -> false
    | TMinus (x161, x162), TMult (x181, x182) -> false
    | TMult (x181, x182), TMinus (x161, x162) -> false
    | TMinus (x161, x162), TUMinus x17 -> false
    | TUMinus x17, TMinus (x161, x162) -> false
    | TPlus (x151, x152), TMod (x201, x202) -> false
    | TMod (x201, x202), TPlus (x151, x152) -> false
    | TPlus (x151, x152), TDiv (x191, x192) -> false
