let rec mfodl_parse
  x = (fun w ->
        bind (srun_w_f (equal_list equal_char) equal_mtok mfodl_parse_gtab
               mfodl_parse_states mfodl_parse_redtab mfodl_parse_pgt
               mfodl_parse_psts mfodl_parse_pcomps mfodl_parse_pfins
               ([(mfodl_parse_i0, mfodl_parse_p0)], (w, [])))
          mfodl_dec_Formula)
        x;;

let rec parse_formula
  s = (match lex s with None -> None
        | Some w -> bind (mfodl_parse w) postprocess);;

let rec integer_of_nat x = of_nat semiring_1_integer x;;

let rec lex_chars s = map_option (map (fun t -> (tok t, lexeme t))) (lex s);;

